  int rankMask = 0;
  for (int i = 0; i < windowSize; i++) {
    int rank = deck[startIdx + i] & 0xF;
    rankMask |= (1 << rank);
  }
  int suitMask = 0;
  for (int i = 0; i < windowSize; i++) {
    int suit = (deck[startIdx + i] >> 4) & 0xF;
    suitMask |= (1 << suit);
  }
  int intersection = rankMask & suitMask;
  int count = 0;
  int bits = 0;
  while (bits < 32) {
    if ((intersection >> bits) & 1 == 1) count++;
    bits++;
  }
  return count;
}

