      }
    } else if (cmd == 'SAVE') {
      totals.add(currentTotal);
    } else if (cmd == 'LOAD') {
      if (totals.isNotEmpty) {
        currentTotal = totals.last;
        stack.clear();
        undoStack.clear();
      }
    }
