void fn0() {

  List<String> text = ["EXAMPLE", "THIS", "IS", "A", "SIMPLE", "EXAMPLE", "HERE"];
  String pattern = "EXAMPLE";

  List<String> combine(List<String> parts) {
    return parts.fold<List<String>>(
      [],
      (List<String> acc, String part) {
        if (part.isEmpty) return acc;
        List<String> newAcc = acc.isNotEmpty ? acc : [];
        for (String existing in acc) {
          newAcc.add(existing + part);
        }
        if (newAcc.isEmpty) {
          newAcc.add(part);
        }
        return newAcc;
      },
    );
  }

  Set<int> search(List<String> text, String pattern) {
    return combine(text).where((String word) {
      if (word.length < pattern.length) return false;
      for (int i = 0; i <= word.length - pattern.length; i++) {
        bool match = true;
        for (int j = 0; j < pattern.length; j++) {
          if (word[i + j] != pattern[j]) {
            match = false;
            break;
          }
        }
        if (match) return true;
      }
      return false;
    }).asMap().keys.toSet();
  }

  Set<int> indices = search(text, pattern);
  print('Pattern found at positions: $indices');

  List<String> combined = combine(text);
  print('Combined text: ${combined.join(" ")}');
}

