void fn0() async {

  final ReceivePort responsePort = ReceivePort();

  await Isolate.spawn(
    _weatherWorker,
    [responsePort.sendPort],
  );

  String city = await stdin
      .readLineAsLowerCase()
      .then((s) => s.isEmpty ? 'London' : s.trim());

  final SendPort workerSendPort = responsePort.first as SendPort;
  workerSendPort.send(city);

  String weather = await responsePort.first;
  print('Current weather: $weather');
