void _weatherWorker(SendPort responsePort) {
  for (String line in stdin.lineByLineSync()) {
    if (line.isEmpty) {
      responsePort.send('');
      continue;
    }
    String parts = line.split(' ').skip(1).join(' ');
    int index = parts.indexOf(':');
    if (index > 0) {
      String city = parts.substring(0, index);
      String temp = parts.substring(index + 1);
      int tempInt = int.parse(temp);
      int index2 = temp.indexOf('.');
      if (index2 > 0) {
        tempInt += int.parse(temp.substring(index2 + 1));
      }
      if (tempInt >= 20) {
        responsePort.send('${city}: Sunny');
      } else if (tempInt >= 10) {
        responsePort.send('${city}: Partly cloudy');
      } else {
        responsePort.send('${city}: Snowing');
      }
    } else {
      responsePort.send('');
    }
  }
}

