  for (int i = 0; i < trace.length; i++) {
    String c = trace[i];
    if (c == '(') {
      stack.add(c);
      depths.add(stack.length);
    } else if (c == ')') {
      if (stack.isEmpty) return false;
      stack.removeLast();
      depths.removeLast();
    } else if (c == '.' && stack.isNotEmpty) {
      depths.removeLast();
      if (depths.isNotEmpty) depths[depths.length - 1]++;
    } else {
      return false;
    }
  }
  return stack.isEmpty && depths.isEmpty;
}

