int fn0(List<int> modules) {
  if (modules.isEmpty) return 0;
  if (modules.length == 1) {
    return modules[0] == 1 ? 1 : 0;
  }
  int n = modules.length;
  List<List<int>> dp = List.generate(n, (_) => List.filled(2, 0));
  dp[0][0] = modules[0] == 1 ? 1 : 0;
  dp[0][1] = modules[0] == 1 ? 0 : 1;
  for (int i = 1; i < n; i++) {
    int take = modules[i] == 1 ? 1 : 0;
    int skip = modules[i] == 1 ? 0 : 1;
    int maxTake = 0;
    int maxSkip = 0;
    for (int j = i - 1; j >= 0; j--) {
      if (modules[i] == modules[j]) {
        int candTake = dp[j][0] + take;
        int candSkip = dp[j][1] + skip;
        if (candTake > maxTake) maxTake = candTake;
        if (candSkip > maxSkip) maxSkip = candSkip;
      }
    }
    dp[i][0] = maxTake;
    dp[i][1] = maxSkip;
  }
  return dp[n - 1][0] > dp[n - 1][1] ? dp[n - 1][0] : dp[n - 1][1];
}

