bool fn0(List<int> requests, int capacity) {
  if (capacity <= 0 || requests.isEmpty) return false;

  int currentLoad = 0;
  for (int r in requests) {
    if (r > 0) {
      currentLoad += r;
      if (currentLoad > capacity) return false;
    } else if (r < 0) {
      currentLoad += r;
    }
  }

  int deficit = 0;
  for (int r in requests) {
    if (r < 0) {
      deficit += -r;
    }
  }

  if (deficit == 0) return true;

  currentLoad = 0;
  int i = 0;
  while (i < requests.length) {
    int j = i;
    while (j < requests.length && requests[j] >= 0) {
      currentLoad += requests[j];
      j++;
    }

    if (currentLoad + deficit <= capacity) return true;

    currentLoad = 0;
    i = j;
  }

  return false;
}

