  if (cols == 0) return false;
  for (int i = 1; i < rows; i++) {
    if (board[i].length != cols) return false;
  }
  int left = 0;
  int right = rows * cols - 1;
  while (left <= right) {
    int mid = left + (right - left) ~/ 2;
    int row = mid ~/ cols;
    int col = mid % cols;
    if (board[row][col] == target) return true;
    if (board[row][col] < target) {
