int fn0(List<List<int>> grid, int threshold) {
  if (grid.isEmpty || grid[0].isEmpty) return 0;
  int rows = grid.length;
  int cols = grid[0].length;
  List<List<bool>> visited = List.generate(rows, (_) => List.filled(cols, false));
  List<List<int>> boundaries = [];

  void dfs(int r, int c, int height) {
    if (r < 0 || c < 0 || r >= rows || c >= cols || visited[r][c]) return;
    visited[r][c] = true;
    if (height > threshold) {
      boundaries.add([r, c]);
    }
    int h = grid[r][c];
    dfs(r - 1, c, h);
    dfs(r + 1, c, h);
    dfs(r, c - 1, h);
    dfs(r, c + 1, h);
  }

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (!visited[r][c] && grid[r][c] > threshold) {
        dfs(r, c, grid[r][c]);
      }
    }
  }

  if (boundaries.isEmpty) return 0;
  int minR = boundaries[0][0], maxR = boundaries[0][0];
  int minC = boundaries[0][1], maxC = boundaries[0][1];
  for (var b in boundaries) {
    if (b[0] < minR) minR = b[0];
    if (b[0] > maxR) maxR = b[0];
    if (b[1] < minC) minC = b[1];
    if (b[1] > maxC) maxC = b[1];
  }
  return (maxR - minR + 1) * (maxC - minC + 1);
}

