  int rows = grid.length;
  int cols = grid[0].length;
  int maxVal = grid[0][0];
  int minVal = grid[0][0];
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      int val = grid[r][c];
      if (val > maxVal) maxVal = val;
      if (val < minVal) minVal = val;
    }
  }
  bool hasAllValues = true;
  int expected = minVal;
  while (hasAllValues && expected <= maxVal) {
    bool exists = false;
    for (int r = 0; r < rows; r++) {
      for (int c = 0; c < cols; c++) {
        if (grid[r][c] == expected) {
          exists = true;
          break;
        }
      }
      if (exists) break;
    }
    if (!exists) hasAllValues = false;
    else expected++;
  }
  if (!hasAllValues) return false;
  List<List<bool>> visited = List.generate(rows, (_) => List.filled(cols, false));
  List<List<int>> directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  int count = 0;
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (!visited[r][c]) {
        bool isPrime = true;
        int val = grid[r][c];
        if (val < 2) {
          isPrime = false;
        } else {
          for (int i = 2; i * i <= val; i++) {
            if (val % i == 0) {
              isPrime = false;
              break;
            }
          }
        }
        if (isPrime) {
          count++;
        }
        visited[r][c] = true;
        for (var dir in directions) {
          int nr = r + dir[0];
