    for (int i = 0; i < args.length; i++) {
      final a = args[i];
      if (a.isEmpty) continue;
      if (parsed.isEmpty && !a.startsWith('-')) {
        print('First argument must be an integer k (size of combinations). Got: $a');
        return;
      }
      final neg = a.startsWith('-');
      final s = neg ? a.substring(1) : a;
      if (s.isEmpty) continue;
      final num = int.tryParse(s);
      if (num == null) {
        print('Invalid integer: $s');
        return;
      }
      if (neg && num >= 0) {
        print('Negative k value not allowed. Got: $a');
        return;
      }
      parsed[num] = a;
    }
    if (parsed.isEmpty) return;
    final keys = parsed.keys.toList()..sort();
    k = keys.first;
    items = keys.skip(1).map((i) => parsed![i]!).toList()..sort();
  }
  print('items = ${items.join(', ')}');
