  }
  for (int i = 1; i < k; i++) {
    total ~/= i;
  }
  print('Total combinations: $total');

  void backtrack(List<int> current, int start) {
    if (current.length == k) {
      print(current.map((i) => items[i]).join(' '));
      return;
    }
    for (int i = start; i < n; i++) {
      current.add(i);
      backtrack(current, i + 1);
      current.removeLast();
    }
  }

  backtrack([], 0);
}

