int _nCr(int n, int k) {
  if (k < 0 || k > n) return 0;
  if (k == 0 || k == n) return 1;

  k = k < n - k ? k : n - k;

  int result = 1;
  for (int i = 0; i < k; i++) {
    result = result * (n - i) ~/ (i + 1);
  }

  return result;
}

