void fn0(List<String> args) {

  int? kArg;
  List<String>? itemArgs;

  if (args.isNotEmpty) {
    kArg = int.tryParse(args[0]);
    itemArgs = args.sublist(1);
  }

  int n = itemArgs != null && itemArgs.isNotEmpty ? itemArgs.length : 4;
  int k = kArg ?? 2;

  if (n <= 0) {
    print('n must be positive. Received: $n');
    print('Usage: dart run <file.dart> <k> <item1> <item2> ...');
    return;
  }

  if (k < 0 || k > n) {
    print('k must be between 0 and $n (inclusive). Received: $k');
    print('Usage: dart run <file.dart> <k> <item1> <item2> ...');
    return;
  }

  if (itemArgs == null || itemArgs.isEmpty) {

    List<String> defaultItems = ['A', 'B', 'C', 'D'];
    itemArgs = defaultItems.sublist(0, n);
  }

  print('items = ${itemArgs.join(', ')}');
  print('k = $k');
  print('Total combinations: ${binomial(n, k)}');

  List<List<String>> result = generateCombinations(itemArgs!, k);
  for (var combo in result) {
    print(combo.join(', '));
  }
}

List<List<String>> generateCombinations(List<String> items, int k) {
  List<List<String>> result = [];
  List<String> current = [];

  void backtrack(int start) {
    if (current.length == k) {
      result.add(List.from(current));
      return;
    }

    for (int i = start; i < items.length; i++) {
      current.add(items[i]);
      backtrack(i + 1);
      current.removeLast();
    }
  }

  backtrack(0);
  return result;
}

int binomial(int n, int k) {
  if (k == 0 || k == n) {
    return 1;
  }
  if (k == 1 || k == n - 1) {
    return n;
  }
  k = k < n - k ? k : n - k;
  int result = 1;
  for (int i = 0; i < k; i++) {
    result = result * (n - i) ~/ (i + 1);
  }
  return result;
}

