  print('Initial deck: $deck');

  var suits = ['Hearts', 'Diamonds', 'Clubs', 'Spades'];
  var suitOrder = <String, int>{
    'Hearts': 0, 'Diamonds': 1, 'Clubs': 2, 'Spades': 3
  };
  var rankOrder = <int, int>{for (var r = 1; r <= 13; r++) r: r};

  var compareCards = (int a, int b) {

    var suitA = a ~/ 13;
    var suitB = b ~/ 13;
    if (suitA != suitB) {
      return suitOrder[suits[suitA]]! - suitOrder[suits[suitB]]!;
    }

    var rankA = a % 13;
    var rankB = b % 13;
    if (rankA != rankB) {
      return rankOrder[rankA]! - rankOrder[rankB]!;
    }

    return a - b; 
  };

  deck.sort(compareCards);
  print('Sorted deck: $deck');
}

