      }
      print(''); 
      return;
    }

    for (int col = 0; col < n; col++) {
      if (isSafe(row, col)) {
        board[row][col] = 1;
        placeQueen(row + 1);

        board[row][col] = 0;
      }
    }
  }

  placeQueen(0);
  print('Total solutions: $solutions');
}

