    for (int i = 0; i < row; i++) {
      if (board[i][col] == 1) {
        return false;
      }
    }

    for (int i = 0; i < row; i++) {
      int j = col - (col - board[i][col]);
      if (j >= 0 && board[i][j] == 1) {
        return false;
      }
      j = col + (board[i][col] - col);
      if (j < n && board[i][j] == 1) {
        return false;
      }
