    }

    double pitch;
    if (sin2x < 0) {
      pitch = (2 * atan2(y, w) - pi) / 2;
    } else {
      pitch = (2 * atan2(y, w) + pi) / 2;
    }

    double roll = atan2(2 * (y * z + w * x), 1 - 2 * (y * y + x * x));

    return Vector3(yaw, pitch, roll);
