class Quaternion {
  double w, x, y, z;

  Quaternion(this.w, this.x, this.y, this.z);

  Quaternion operator +(Quaternion other) {
    return Quaternion(
      w + other.w,
      x + other.x,
      y + other.y,
      z + other.z,
    );
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(
      w - other.w,
      x - other.x,
      y - other.y,
      z - other.z,
    );
  }

  Quaternion operator *(Quaternion other) {
    double nw = w * other.w - x * other.x - y * other.y - z * other.z;
    double nx = w * other.x + x * other.w + y * other.z - z * other.y;
    double ny = w * other.y - x * other.z + y * other.w + z * other.x;
    double nz = w * other.z + x * other.y - y * other.x + z * other.w;
    return Quaternion(nw, nx, ny, nz);
  }

  double norm() {
    return sqrt(w * w + x * x + y * y + z * z);
  }

  Quaternion normalized() {
    double n = norm();
    return Quaternion(w / n, x / n, y / n, z / n);
  }

  Quaternion conjugate() {
    return Quaternion(w, -x, -y, -z);
  }

  Quaternion inverse() {
    return conjugate() * (1 / norm() * norm());
  }

  @override
  String toString() {
    return 'Quaternion($w, $x, $y, $z)';
  }
}

