class Quaternion {
  final double r;
  final double i;
  final double j;
  final double k;

  const Quaternion(this.r, this.i, this.j, this.k);

  double get norm => sqrt(r * r + i * i + j * j + k * k);

  Quaternion normalized() => scale(1 / norm);

  Quaternion scale(double factor) =>
      Quaternion(r * factor, i * factor, j * factor, k * factor);

  Quaternion add(Quaternion other) =>
      Quaternion(r + other.r, i + other.i, j + other.j, k + other.k);

  Quaternion multiply(Quaternion other) {
    final newR = r * other.r - i * other.i - j * other.j - k * other.k;
    final newI = r * other.i + i * other.r + j * other.k - k * other.j;
    final newJ = r * other.j - i * other.k + j * other.r + k * other.i;
    final newK = r * other.k + i * other.j - j * other.i + k * other.r;
    return Quaternion(newR, newI, newJ, newK);
  }

  Quaternion inverse() =>
      normalized().scale(norm.pow(2)).conjugate();

  Quaternion conjugate() =>
      Quaternion(r, -i, -j, -k);

  @override
  String toString() {
    final parts = [r.toString()];
    if (i.abs() > 1e-6) parts.add('${i > 0 ? '+' : '-'}${i.abs().toString()}i');
    if (j.abs() > 1e-6) parts.add('${j > 0 ? '+' : '-'}${j.abs().toString()}j');
    if (k.abs() > 1e-6) parts.add('${k > 0 ? '+' : '-'}${k.abs().toString()}k');
    return parts.join();
  }
}

extension on Quaternion {

  Quaternion axisAngleToQuaternion(double angle) {
    final h = angle / 2;
    final s = sin(h);
    return Quaternion(
      cos(h),
      i * s,
      j * s,
      k * s,
    );
  }
}

