  int digit = 0;
  int special = 0;
  int lengthBonus = 0;
  int strength = 0;

  for (int i = 0; i < password.length; i++) {
    String ch = password[i];
    if (ch.codeUnitAt(0) >= 97 && ch.codeUnitAt(0) <= 122) {
      lower = 1;
    } else if (ch.codeUnitAt(0) >= 65 && ch.codeUnitAt(0) <= 90) {
      upper = 1;
    } else if (ch.codeUnitAt(0) >= 48 && ch.codeUnitAt(0) <= 57) {
      digit = 1;
    } else {
      special = 1;
    }
  }

  strength += lower + upper + digit + special;

  if (password.length >= 8) {
    strength += 2;
  }

  if (strength >= 8) {
    lengthBonus = password.length - 7;
  } else if (strength >= 6) {
    lengthBonus = password.length - 6;
  } else if (strength >= 4) {
    lengthBonus = password.length - 4;
  } else {
    lengthBonus = 0;
  }

  strength += lengthBonus;

  bool hasRepeated = false;
  for (int i = 1; i < password.length; i++) {
    if (password[i] == password[i - 1]) {
      hasRepeated = true;
      break;
    }
  }
  if (hasRepeated) strength -= 1;

  List<int> result = [];
  for (int i = 0; i < password.length; i++) {
    int value = 0;
    if (i >= strength) {
      value = password[i].codeUnitAt(0) * 2;
    } else {
      value = password[i].codeUnitAt(0);
    }
    result.add(value);
  }
  return result;
}

