double fn0(List<String> logs) {
  final Map<String, int> moduleCounts = {};
  final Map<String, int> priorityCounts = {};
  final Map<String, List<String>> priorityModules = {};
  final Set<String> allModules = {};
  int totalCritical = 0;
  int totalModules = 0;
  int minPriority = 100;
  int maxPriority = -1;

  for (final String log in logs) {
    final parts = log.split(':');
    if (parts.length != 2) continue;

    final module = parts[0];
    final details = parts[1];
    allModules.add(module);

    final severity = details[0];
    final priorityChar = details[1];
    final count = int.parse(details[2]);

    final priority = priorityChar == 'C'
        ? 0
        : priorityChar == 'M'
            ? 1
            : priorityChar == 'S'
                ? 2
                : priorityChar == 'R'
                    ? 3
                    : priorityChar == 'P'
                        ? 4
                        : priorityChar == 'B'
                            ? 5
                            : 6;

    moduleCounts[module] = (moduleCounts[module] ?? 0) + count;
    priorityCounts[severity] = (priorityCounts[severity] ?? 0) + count;
    totalModules += count;

    if (severity == 'C') {
      totalCritical += count;
    }

    if (priority < minPriority) {
      minPriority = priority;
    }
    if (priority > maxPriority) {
      maxPriority = priority;
    }

    priorityModules.putIfAbsent(priority, () => []).add(module);
  }

  final Map<String, double> weightedPriorities = {};
  for (final priority in priorityModules.keys) {
    final modules = priorityModules[priority]!;
    final weighted = priority * modules.length;
    weightedPriorities[priority] = weightedPriorities[priority] ?? 0.0 + weighted;
  }

  double score = 0.0;
  if (allModules.isNotEmpty) {
    score += (totalCritical / totalModules) * 0.25;
    score += priorityCounts.length * 0.25;
    score += (minPriority == 6 ? 0.25 : 0.5);
    score += (maxPriority == 0 ? 0.25 : 0.5);
    score += (weightedPriorities.length == 3 ? 0.25 : 0.5);
  }

  return score;
}

