            if (numeric) {
              int id = int.parse(idPart);
              int weight = 0;
              if (levelPart == 'B') weight = 2;
              else if (levelPart == 'C') weight = 3;
              else if (levelPart == 'D') weight = 5;
              else if (levelPart == 'M') weight = 7;
              else if (levelPart == 'P') weight = 11;
              else if (levelPart == 'R') weight = 13;
              else if (levelPart == 'S') weight = 17;
              score += weight * id;
              int tokenLen = token.length;
              if (tokenLen > maxLen) maxLen = tokenLen;
            }
          }
        }
      }
    }
  }
