      String ch = op;
      if (ch == 'M') {
        if (stack.isNotEmpty) total += stack.removeLast();
      } else if (ch == 'P') {
        if (stack.isNotEmpty) total -= stack.removeLast();
      } else if (ch == 'D') {
        if (stack.isNotEmpty) stack[stack.length - 1] *= 2;
      } else if (ch == 'S') {
        if (stack.isNotEmpty) stack[stack.length - 1] /= 2;
      } else if (ch == 'R') {
        if (stack.isNotEmpty) stack.removeLast();
      } else if (ch == 'B') {
        if (stack.isNotEmpty) {
          double val = stack.removeLast();
          stack.add(val);
          stack.add(0.0);
        }
      } else if (ch == '(') {
        stack.add(0.0);
        bracketCount++;
      } else if (ch == ')') {
        if (bracketCount > 0) {
          stack.removeLast();
          bracketCount--;
        }
      } else {
        double val = double.parse(ch);
        stack.add(val);
        total += val;
      }
    } else {
      double val = double.parse(op.substring(1));
      stack.add(val);
      total += val;
    }
  }

  return total;
}

