    'G': 'S',
  };

  Set<String> peakModes = {'M', 'P'};
  int peakCount = 0;
  int regularCount = 0;
  int total = 0;

  for (String day in dailyCounts.keys) {
    if (!peakModes.contains(day)) continue;
    peakCount += dailyCounts[day]!;
  }

  for (String day in dailyCounts.keys) {
    if (peakModes.contains(day)) continue;
    regularCount += dailyCounts[day]!;
  }

  for (String day in dayOfWeek.keys) {
    if (dailyCounts[day] == 2) {
      total++;
    }
  }

  double score = 0.0;
  score += peakCount * 0.25;
  score += regularCount * 0.15;
