  double total = 0.0;
  int state = 0;
  String prev = '';
  int prevH = 0;
  int prevM = 0;
  List<String> tokens = schedule.split(' ');

  for (String token in tokens) {
    if (token.length < 2) continue;
    int colon = token.indexOf(':');
    if (colon <= 0 || colon + 2 >= token.length) continue;
    String timePart = token.substring(0, colon);
    String code = token.substring(colon + 1);

    if (code.length < 2) continue;
    String t = timePart;
    int h = int.parse(t.substring(0, 2));
    int m = int.parse(t.substring(3, 5));

    int codeH = 0;
    int codeM = 0;
    for (int i = 0; i < code.length; i++) {
      int c = code.codeUnitAt(i);
      if (c >= 65 && c <= 90) {
        codeH += c - 64;
        codeM += c - 64;
      } else if (c >= 97 && c <= 122) {
        codeH += c - 70;
        codeM += c - 70;
      }
    }
    codeH %= 12;
    codeM %= 60;

    if (state == 0) {
      state = 1;
      prev = code;
      prevH = h;
      prevM = m;
    } else if (state == 1) {
      if (code == prev) {
        state = 2;
      } else {
        state = 0;
      }
      prev = code;
      prevH = h;
      prevM = m;
    } else if (state == 2) {
      int hh = (prevH + codeH) % 24;
      int mm = (prevM + codeM) % 60;
      if (hh == h && mm == m) {
        total += 0.5;
        prev = code;
        prevH = h;
        prevM = m;
      } else {
        state = 0;
      }
    }
  }
  return total;
}

