      int count = 0;
      int sum = 0;
      for (int s = t; s <= totalTransfers; s++) {
        if (!cooldowns.containsKey(s)) {
          count++;
          sum += stack[s - 1];
        } else {
          break;
        }
      }
      if (count > bestTransfer) {
        bestTransfer = count;
        bestBalance = sum;
      }
    }
  }

  int bestNet = 0;
  for (int t = 1; t <= totalTransfers; t++) {
    int net = 0;
