  final List<int> closeDays = [2, 4, 6];
  final int days = 6;

  final List<List<int>> dp = List.generate(
    days + 1,
    (_) => List.filled(openDays.length + 1, 0),
  );

  for (int d = 1; d <= days; d++) {
    for (int i = 0; i <= openDays.length; i++) {
      if (i == 0) {

        dp[d][i] = -1000000;
        continue;
      }
      if (d < openDays[i - 1]) {

        dp[d][i] = -1000000;
        continue;
      }
      int profit = 0;
      int prevCloseIndex = i - 1;
      int prevCloseDay = closeDays[prevCloseIndex];
      if (prevCloseDay < d) {
        profit = d - prevCloseDay;
      }
      int prevOpenDay = openDays[i - 1];
      int holdingDays = d - prevOpenDay;
      profit -= holdingDays;
      int previousBest = dp[prevOpenDay][i - 1];
      if (previousBest == -1000000) {

        dp[d][i] = -1000000;
        continue;
      }
      dp[d][i] = previousBest + profit;
    }
  }

  int best = -1000000;
  for (int i = 0; i <= openDays.length; i++) {
    if (dp[days][i] > best) {
      best = dp[days][i];
    }
  }

  if (best == -1000000) {
    print('FINAL: -1');
  } else {
    print('FINAL: $best');
  }
}

