  List<String> events = [];
  double net = 0.0;
  int openCount = 0;

  for (int i = 0; i < sequence.length; i++) {
    String ch = sequence[i];
    if (ch == 'C' || ch == 'D') {
      if (i + 1 < sequence.length) {
        String token = sequence.substring(i + 1, sequence.indexOf(':', i + 1));
        int colonIdx = sequence.indexOf(':', i + 1);
