            net += price * qty;
            prices.add(price);
            quantities.add(qty);
            events.add(ch);
          } else if (ch == 'D') {
            net -= price * qty;
            prices.add(price);
            quantities.add(qty);
            events.add(ch);
          }
          openCount += ch == 'C' ? 1 : -1;
          i = colonIdx;
        }
      }
    }
  }

  if (openCount > 0) {
    return "OPEN";
  }

  double discount = 0.0;
  for (int i = 0; i < prices.length; i++) {
