    int qty = quantities[i];
    double total = price * qty;
    if (i % 2 == 0) {
      discount += total * 0.05;
    } else {
      discount += total * 0.10;
    }
  }

  double finalNet = net - discount;
  return "FINAL:$finalNet,net=$net,result=${finalNet > 0 ? 'POSITIVE' : 'NEGATIVE'}";
}

