int fn0(List<List<int>> grid) {
  if (grid.isEmpty || grid[0].isEmpty) return 0;
  final rows = grid.length;
  final cols = grid[0].length;
  final visited = List.generate(rows, (_) => List.filled(cols, false));
  int count = 0;

  bool isLand(int r, int c) {
    return grid[r][c] == 1;
  }

  bool isValid(int r, int c) {
    return r >= 0 && r < rows && c >= 0 && c < cols;
  }

  void dfs(int r, int c) {
    if (!isValid(r, c) || !isLand(r, c) || visited[r][c]) return;
    visited[r][c] = true;
    dfs(r + 1, c);
    dfs(r - 1, c);
    dfs(r, c + 1);
    dfs(r, c - 1);
  }

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (isLand(r, c) && !visited[r][c]) {
        dfs(r, c);
        count++;
      }
    }
  }

  int total = count * 4;
  if (count > 1) total -= 2;
  return total;
}

