    for (int r = 0; r < rows; r++) {
      int value = row[r];
      int top = (c + 1 < rows) ? dp[r][c + 1] : -999999;
      int bottom = (c + 2 < rows) ? dp[r][c + 2] : -999999;
      int left = (r > 0) ? dp[r - 1][c + 1] : -999999;
      int right = (r < rows - 1) ? dp[r + 1][c + 1] : -999999;
      int best = value + top;
      if (bottom > best) best = bottom;
      if (left > best) best = left;
      if (right > best) best = right;
      dp[r][c] = best;
    }
  }

  int best = -999999;
  for (int r = 0; r < rows; r++) {
    if (dp[r][0] > best) best = dp[r][0];
  }
