class Role {
  final String name;
  final Map<String, bool> permissions;
  final List<String> subRoles;

  Role(this.name, {required this.permissions, required this.subRoles});

  bool hasPermission(String action, String resource) {
    return permissions[action + ":" + resource] ?? false;
  }

  void addPermission(String action, String resource) {
    permissions[action + ":" + resource] = true;
  }

  void removePermission(String action, String resource) {
    permissions[action + ":" + resource] = false;
  }

  void grantSubRole(Role role) {
    subRoles.add(role.name);
    for (var perm in role.permissions.entries) {
      if (perm.value!) {
        addPermission(perm.key.split(":")[0], perm.key.split(":")[1]);
      }
    }
  }

  @override
  String toString() {
    return 'Role{name: $name, permissions: $permissions, subRoles: $subRoles}';
  }
}

