      combinations.add(singleItem);
    }
  }

  for (var i = 0; i < frequentItemsets.length; i++) {
    for (var j = i + 1; j < frequentItemsets.length; j++) {
      Set<String> union = frequentItemsets[i].union(frequentItemsets[j]);
      if (union.length == k) {
        combinations.add(union);
      }
    }
  }

