int fn0(List<String> grid, int startRow, int startCol, int targetRow, int targetCol, int maxSteps) {
  if (grid.isEmpty || startRow < 0 || startRow >= grid.length || startCol < 0 || startCol >= grid[0].length) {
    return -1;
  }

  List<List<int>> directions = [
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1]
  ];

  List<List<bool>> visited = List.generate(
    grid.length,
    (_) => List.filled(grid[0].length, false),
  );

  void dfs(int row, int col, int stepsRemaining) {
    if (row == targetRow && col == targetCol) {
      if (stepsRemaining >= 0) {
        result = stepsRemaining;
      }
      return;
    }
    if (stepsRemaining < 0) {
      return;
    }

    visited[row][col] = true;

    for (List<int> d in directions) {
      int newRow = row + d[0];
      int newCol = col + d[1];
      if (newRow >= 0 &&
          newRow < grid.length &&
          newCol >= 0 &&
          newCol < grid[0].length &&
          !visited[newRow][newCol] &&
          grid[newRow][newCol] != '#') {
        dfs(newRow, newCol, stepsRemaining - 1);
      }
    }

    visited[row][col] = false;
  }

  int result = -1;
  dfs(startRow, startCol, maxSteps);
  return result;
}

