List<int> fn0(List<List<int>> grid) {
  int rows = grid.length;
  if (rows == 0) return [];
  int cols = grid[0].length;
  if (cols == 0) return [];
  List<int> result = [];
  void dfs(int r, int c, int depth, int parentR, int parentC, int state) {
    if (state == 2) return;
    if (depth > 3) {
      if (state == 1) {
        result.add(grid[r][c]);
      }
      return;
    }
    List<List<int>> neighbors = [];
    if (r > 0) neighbors.add([r - 1, c]);
    if (c < cols - 1) neighbors.add([r, c + 1]);
    if (r < rows - 1) neighbors.add([r + 1, c]);
    if (c > 0) neighbors.add([r, c - 1]);
    bool hasGuard = false;
    int safeCount = 0;
    int riskyCount = 0;
    int dangerousCount = 0;
    int guardReach = 0;
    for (List<int> n in neighbors) {
      int nr = n[0], nc = n[1];
      if (grid[nr][nc] == 1) {
        hasGuard = true;
      } else if (grid[nr][nc] == 2) {
        safeCount++;
      } else if (grid[nr][nc] == 3) {
        riskyCount++;
      } else {
        dangerousCount++;
      }
      if (grid[nr][nc] == 0) {
        guardReach++;
      }
    }
    bool isCritical = false;
    if (hasGuard) {
      if (state == 1) {
        isCritical = riskyCount + dangerousCount >= 2;
      } else {
        isCritical = dangerousCount >= 1;
      }
    } else {
      isCritical = safeCount + riskyCount + dangerousCount >= 3;
    }
    if (isCritical) {
      dfs(r, c, depth + 1, -1, -1, 1);
    } else {
      if (state == 1) {
        if (hasGuard) {
          result.add(grid[r][c]);
        }
        for (List<int> n in neighbors) {
          dfs(n[0], n[1], depth + 1, r, c, 2);
        }
      } else {
        int bestReach = -1;
        for (List<int> n in neighbors) {
          int nr = n[0], nc = n[1];
          if (grid[nr][nc] == 0 && guardReach > bestReach) {
            bestReach = guardReach;
            dfs(nr, nc, depth + 1, r, c, 2);
          }
        }
      }
    }
  }
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (grid[r][c] == 0) {
        dfs(r, c, 0, -1, -1, 0);
      }
    }
  }
  return result;
}

