    return -1;
  }
  if (quantities.isEmpty || budget < 0) {
    return 0;
  }

  int total = 0;
  int count = 0;

  for (int i = 0; i < quantities.length; i++) {
    if (quantities[i] <= 0) {
      continue;
    }

    final int baseCost = quantities[i] * unitPrices[i];
    final int discountAmount = (baseCost * discounts[i]) ~/ 100;
    final int discountedCost = baseCost - discountAmount;

    if (total + discountedCost <= budget) {
      total += discountedCost;
      count++;
    } else {
      final int remaining = budget - total;
      final int fullBundles = remaining ~/ baseCost;
      if (fullBundles > 0) {
        total += fullBundles * baseCost;
        count += fullBundles;
      }
      break;
    }
  }

  return count;
}

