    if (selected.contains(i)) {
      int gap = moduleDurations[i] - previous;
      gaps.add(gap);

      previous = moduleDurations[i];
    }
  }

  if (selected.contains(moduleDurations.length - 1)) {
    gaps.add(moduleDurations.last - previous);
  }

  for (int g in gaps) {
    if (g >= maxGap) {
      selected = <int>{};
      break;
    }
  }

  return selected;
}

