Set<int> fn0(int startFloor, List<int> requestedFloors) {
  Map<int, int> requests = {};
  int left = 0;
  int right = requestedFloors.length - 1;
  int? peak;
  while (left <= right) {
    int mid = left + ((right - left) >> 1);
    int val = requestedFloors[mid];
    requests[val] = (requests[val] ?? 0) + 1;
    int dist = (val - startFloor).abs();
    if (peak == null || dist < peak!.distance) {
      peak = Distance(val, dist);
    } else if (dist == peak!.distance) {
      if (val < peak!.floor) {
        peak = Distance(val, dist);
      }
    }
    if (val >= startFloor) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }
  int lo = 0;
  int hi = requestedFloors.length - 1;
  int? firstPeakIndex;
  while (lo <= hi) {
    int mid = lo + ((hi - lo) >> 1);
    int val = requestedFloors[mid];
    int dist = (val - startFloor).abs();
    if (dist < peak!.distance) {
      lo = mid + 1;
    } else if (dist == peak!.distance && val < peak!.floor) {
      lo = mid + 1;
    } else {
      firstPeakIndex = mid;
      hi = mid - 1;
    }
  }
  Set<int> result = {};
  for (int i = firstPeakIndex!; i < requestedFloors.length; i++) {
    int floor = requestedFloors[i];
    if (requests[floor]! > 1) {
      result.add(floor);
    }
  }
  return result;
}

