@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<int> arr = [64, 25, 12, 22, 11];
  int n = arr.length;

  if (n <= 1) {
    print('Sorted array: $arr');
    return;
  }

  List<int> aux = List<int>.filled(n, 0);

  void merge(int left, int mid, int right) {
    int i = left;
    int j = mid + 1;
    int k = left;

    while (i <= mid && j <= right) {
      if (arr[i] <= arr[j]) {
        aux[k++] = arr[i++];
      } else {
        aux[k++] = arr[j++];
      }
    }

    while (i <= mid) {
      aux[k++] = arr[i++];
    }

    while (j <= right) {
      aux[k++] = arr[j++];
    }

    for (i = left; i <= right; i++) {
      arr[i] = aux[i];
    }
  }

  void mergeSort(int left, int right) {
    if (left < right) {
      int mid = (left + right) ~/ 2;
      mergeSort(left, mid);
      mergeSort(mid + 1, right);
      merge(left, mid, right);
    }
  }

  mergeSort(0, n - 1);

  print('Sorted array: $arr');
}

