  List<double> lo = List<double>.filled(n, 0);
  List<double> hi = List<double>.filled(n, 0);
  lo[0] = values[0];
  hi[0] = values[0];

  for (int i = 1; i < n; i++) {
    lo[i] = values[i] < lo[i - 1] ? values[i] : lo[i - 1];
    hi[i] = values[i] > hi[i - 1] ? values[i] : hi[i - 1];
  }

  double span = hi[n - 1] - lo[n - 1];
  return 'Day $n: ${lo[n - 1].toStringAsFixed(1)}-${hi[n - 1].toStringAsFixed(1)}cm ($span cm span)';
}

