String fn0(List<String> readings) {
  if (readings.isEmpty) return "No readings";

  List<double> h = [];
  List<int> d = [];
  for (String r in readings) {
    List<String> p = r.split(' ');
    h.add(double.parse(p[0]));
    d.add(int.parse(p[1]));
  }

  double maxH = -1, minH = double.infinity;
  int maxD = -1, minD = double.infinity;
  for (int i = 0; i < h.length; i++) {
    if (h[i] > maxH) maxH = h[i];
    if (h[i] < minH) minH = h[i];
    if (d[i] > maxD) maxD = d[i];
    if (d[i] < minD) minD = d[i];
  }

  int rangeDays = maxD - minD + 1;
  List<double> bins = List.filled(rangeDays, 0);
  for (int i = 0; i < h.length; i++) {
    int bin = (h[i] - minH) * rangeDays / (maxH - minH);
    bins[bin < rangeDays ? bin : rangeDays - 1]++;
  }

  int maxBinCount = -1;
  for (int b in bins) {
    if (b > maxBinCount) maxBinCount = b;
  }

  List<String> bars = [];
  for (int b in bins) {
    String bar = String.fromCharCodes(List.filled(b, 0x2588));
    bars.add(bar);
  }

  return "Day ${minD}-${maxD} (${(maxH - minH).toStringAsFixed(1)} cm range)\n" +
         bars.join('\n');
}

