        double dx = data[i][0] - currentCentroids[j][0];
        double dy = data[i][1] - currentCentroids[j][1];
        double dist = dx * dx + dy * dy;

        if (dist < minDist) {
          minDist = dist;
          bestCluster = j;
        }
      }

      if (assignments[i][0] != bestCluster) {
        converged = false;
      }

      assignments[i][0] = bestCluster;
    }

