  if (packetSizes.isEmpty) return true;
  if (packetSizes.length == 1) {
    return packetSizes[0] >= 1 && packetSizes[0] <= 1000;
  }

  int total = 0;
  for (int s in packetSizes) {
    total += s;
  }
  if (total < 1000) return false;

  int minStart = 1000000000;
  int maxEnd = -1000000000;
  int left = 0;
  int sum = 0;

  for (int right = 0; right < packetSizes.length; right++) {
    sum += packetSizes[right];
    while (sum > 1000 && left <= right) {
      sum -= packetSizes[left];
      left++;
    }
    if (sum == 1000 && left <= right) {
      int start = left + 1;
      int end = right + 1;
      if (end - start >= maxGap) return true;
      if (packetSizes[start - 1] > packetSizes[end]) {
        minStart = start;
      } else {
        if (start < minStart) minStart = start;
      }
      if (packetSizes[end] > packetSizes[start]) {
        maxEnd = end;
      } else {
        if (end > maxEnd) maxEnd = end;
      }
    }
  }

  return false;
}

