int fn0(List<List<int>> inventory, int maxWeight, int minCount) {
  if (inventory.isEmpty || inventory[0].length < 2) return 0;
  final rows = inventory.length;
  final cols = inventory[0].length;
  int total = 0;
  for (int r = 0; r < rows; r++) {
