bool fn0(List<List<int>> timetable, int startDay, int endDay, int maxGap) {
  if (startDay > endDay) return false;
  if (timetable.isEmpty) return true;

  int? lastDeparture;
  final Map<int, int> nextDeparture = {};

  for (final route in timetable) {
    if (route.length < 2) continue;
    int delay = route[1];
    for (int i = 2; i < route.length; i++) {
      final int day = route[i];
      if (day >= startDay && day <= endDay) {
        final int dep = day - delay;
        if (lastDeparture == null || dep > lastDeparture) {
          nextDeparture[dep] = (nextDeparture[dep] ?? 0) + 1;
        }
        lastDeparture = dep;
      }
    }
  }

  if (nextDeparture.isEmpty) return true;

  final List<int> departures = nextDeparture.keys.toList()..sort();
  int count = 0;

  for (int i = 0; i < departures.length; i++) {
    final int d = departures[i];
    if (i == 0 || (d - departures[i - 1]) > maxGap) {
      count++;
    }
  }

  return count <= 1;
}

