@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<int> digits, int maxConsecutiveFailures) {
  int n = digits.length;
  if (n < 2) return false;
  List<List<int>> dp = List.generate(n, (_) => [0, 0]);

  for (int i = 0; i < n; i++) {
    if (i > 0) {
      if (digits[i] > digits[i - 1]) {
        dp[i][0] = dp[i - 1][0] + 1;
        dp[i][1] = dp[i - 1][1];
      } else if (digits[i] < digits[i - 1]) {
        dp[i][1] = dp[i - 1][1] + 1;
        dp[i][0] = dp[i - 1][0];
      } else {
        dp[i][0] = dp[i - 1][0];
        dp[i][1] = dp[i - 1][1];
      }
    }
    if (dp[i][0] > maxConsecutiveFailures) {
      return false;
    }
  }
  return dp[n - 1][0] >= 2 || dp[n - 1][1] >= 2;
}

