    int prevDay = intervals[j - 1][0];
    int currDay = intervals[j][0];
    if (currDay > prevDay) continue;

    int prevLow = intervals[j - 1][1];
    int prevHigh = intervals[j - 1][2];
    int currLow = intervals[j][1];
    int currHigh = intervals[j][2];

    bool prevWrap = prevLow > prevHigh;
    bool currWrap = currLow > currHigh;

    if (prevDay == currDay) {
      if (currWrap) continue;

      if (prevWrap) {
        if (currLow >= prevLow || currHigh <= prevHigh) return false;
      } else {
        if (currLow <= prevHigh) return false;
      }
    } else if (prevHigh >= 59 && currLow <= 0) {
