  for (int right = 0; right < strengths.length; right++) {
    int val = strengths[right];
    if (val < minStrength) minStrength = val;
    if (val > maxStrength) maxStrength = val;

    while (maxStrength - minStrength > maxVariance) {
      int leftVal = strengths[left];
      if (leftVal == minStrength) minStrength = strengths[left + 1];
      if (leftVal == maxStrength) maxStrength = strengths[left + 1];
