int fn0(String password, String pattern) {
  if (password.isEmpty || pattern.isEmpty) {
    return 0;
  }

  int backspace(String s) {
    int i = 0;
    List<String> stack = [];
    while (i < s.length) {
      if (s[i] == '#') {
        if (stack.isNotEmpty) stack.removeLast();
        i++;
      } else {
        stack.add(s[i]);
        i++;
      }
    }
    return int.parse(stack.join(''));
  }

  int n = password.length, m = pattern.length;
  List<bool> dp = List.filled(n + 1, false);
  dp[0] = true;
  int left = 0;
  for (int right = 0; right < m; right++) {
    if (pattern[right] == '#') {
      left++;
    } else {
      while (left < n && password[left] != pattern[right]) {
        left++;
      }
      if (left >= n) {
        for (int i = 0; i <= n; i++) {
          dp[i] = false;
        }
        left = 0;
        continue;
      }
      List<bool> nextDp = List.filled(n + 1, false);
      for (int j = 0; j <= n; j++) {
        if (!dp[j]) continue;
        if (j > left) nextDp[j] = true;
        if (j + 1 <= n && password[j] == pattern[right]) {
          nextDp[j + 1] = true;
        }
      }
      dp = nextDp;
      left++;
    }
  }
  return dp.fold(0, (sum, val) => sum + (val ? 1 : 0));
}

